#!/usr/bin/env python3
"""Inject the build-time "edition" hook into the Rust sources.

Why a patch instead of a committed change: the self-hosted server info must never
live in a committed source file. This script only adds a small, edition-neutral hook
that reads the value from the CI build environment, so the sources in the repo stay
stock. Idempotent -- running it twice is a no-op.

Hooks added:
  * build.rs    : forwards RD_* env vars into $OUT_DIR/rd_edition_gen.rs (so cargo
                  rebuilds when they change, avoiding stale `option_env!` values).
  * common.rs   : seeds HARD_SETTINGS["conn-type"] and, for the incoming edition,
                  OVERWRITE_SETTINGS (id server + key) and the hidden-server-settings
                  builtin, from the generated constants. Called from load_custom_client(),
                  which every entry point (core_main, flutter ffi, ...) already goes through.
"""

import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parents[2]

COMMON_RS_ANCHOR = "pub fn load_custom_client() {\n"
COMMON_RS_HOOK = '''// RD_EDITION_HOOK_BEGIN (generated by .github/scripts/rd_edition_patch.py)
include!(concat!(env!("OUT_DIR"), "/rd_edition_gen.rs"));

fn apply_builtin_edition() {
    if RD_CONN_TYPE.is_empty() {
        return;
    }
    config::HARD_SETTINGS
        .write()
        .unwrap()
        .insert("conn-type".to_owned(), RD_CONN_TYPE.to_owned());
    if RD_CONN_TYPE == "incoming" {
        if !RD_RENDEZVOUS_SERVER.is_empty() {
            let mut settings = config::OVERWRITE_SETTINGS.write().unwrap();
            settings.insert(
                "custom-rendezvous-server".to_owned(),
                RD_RENDEZVOUS_SERVER.to_owned(),
            );
            if !RD_KEY.is_empty() {
                settings.insert("key".to_owned(), RD_KEY.to_owned());
            }
        }
        if RD_HIDE_SERVER_SETTINGS == "Y" {
            config::BUILTIN_SETTINGS
                .write()
                .unwrap()
                .insert("hide-server-settings".to_owned(), "Y".to_owned());
        }
    }
}
// RD_EDITION_HOOK_END

pub fn load_custom_client() {
    apply_builtin_edition();
'''

BUILD_RS_ANCHOR = "fn main() {\n    hbb_common::gen_version();\n"
BUILD_RS_HOOK = '''// RD_EDITION_HOOK_BEGIN (generated by .github/scripts/rd_edition_patch.py)
fn gen_edition_env() {
    let mut out = String::new();
    for k in [
        "RD_CONN_TYPE",
        "RD_RENDEZVOUS_SERVER",
        "RD_KEY",
        "RD_HIDE_SERVER_SETTINGS",
    ] {
        println!("cargo:rerun-if-env-changed={}", k);
        out.push_str(&format!(
            "pub const {}: &str = {:?};\\n",
            k,
            std::env::var(k).unwrap_or_default()
        ));
    }
    let dir = std::env::var("OUT_DIR").unwrap();
    std::fs::write(std::path::Path::new(&dir).join("rd_edition_gen.rs"), out).unwrap();
}
// RD_EDITION_HOOK_END

fn main() {
    gen_edition_env();
    hbb_common::gen_version();
'''


def patch(rel_path: str, anchor: str, hook: str) -> None:
    path = ROOT / rel_path
    src = path.read_text(encoding="utf-8").replace("\r\n", "\n")
    if "RD_EDITION_HOOK_BEGIN" in src:
        print(f"already patched: {rel_path}")
        return
    if src.count(anchor) != 1:
        sys.exit(f"unexpected anchor count in {rel_path}: {src.count(anchor)}")
    path.write_bytes(src.replace(anchor, hook, 1).encode("utf-8"))
    print(f"patched: {rel_path}")


def main() -> None:
    patch("src/common.rs", COMMON_RS_ANCHOR, COMMON_RS_HOOK)
    patch("build.rs", BUILD_RS_ANCHOR, BUILD_RS_HOOK)


if __name__ == "__main__":
    main()
